async function execute(input){const action=String(input.action||''),id=String(input.project_id||'').trim();if(!id)throw new Error('project_id is required');const base='/api/validation/projects/'+encodeURIComponent(id);if(action==='get'){const value=await call(base);return{status:'succeeded',project_id:id,revision:value.current_revision,included_files:{'validation.py':value.source},manifest:manifest(value)}}if(action==='validate_source'){if(!input.source)throw new Error('validation.py source is required');const value=await call('/api/validation/validate',{method:'POST',body:JSON.stringify({source:input.source})});return{status:'succeeded',validation:{valid:true,warnings_count:Array.isArray(value.warnings)?value.warnings.length:0},manifest:manifest(value)}}const current=await call(base);if(input.confirm_write!==true)throw new Error('Editing validation.py requires confirm_write=true');let value;if(action==='update_parameters'){if(!Array.isArray(input.edits)||!input.edits.length)throw new Error('edits are required');value=await call(base+'/parameters',{method:'POST',body:JSON.stringify({edits:input.edits,expected_source_sha256:current.source_sha256,confirm_write:true})})}else throw new Error('unsupported validation source action');return writeResult(id,value)}
